    valid_date('15-01-2012') => False

    valid_date('04-0-2040') => False

    valid_date('06-04-2020') => True

    valid_date('06/04/2020') => False
    """
    try:
        # Rule 1: The date string is not empty.
        if not date:
            return False

        # Rule 4: The date should be in the format mm-dd-yyyy
        month, day, year = date.split('-')

        # Ensure components are numeric strings
        if not (month.isdigit() and day.isdigit() and year.isdigit()):
            return False

        # Ensure correct lengths: mm, dd, yyyy
        if len(month) != 2 or len(day) != 2 or len(year) != 4:
            return False

        month = int(month)
        day = int(day)
        year = int(year)

        # Rule 3: The months should not be less than 1 or higher than 12.
        if month < 1 or month > 12:
